import { BaseUploadEvent } from './BaseUploadEvent';
import { UploadHandle } from '../Upload.js';
/**
 * The `onCancel` event.
 */
export interface UploadOnCancelEvent extends BaseUploadEvent<UploadHandle> {
    /**
     * The unique identifier of the group (batch) of one or more files that is cancelled.
     */
    uid: string;
}
